          h("div", { className: "mb-4 flex flex-wrap items-center gap-2" }, [
            h("span", { className: "text-sm" }, "Chart range:"),
            h(SelectInput, { value: String(revDays), onChange: (e) => setRevDays(Number(e.target.value)) }, [
              h("option", { value: "7" }, "7 days"),
              h("option", { value: "30" }, "30 days"),
              h("option", { value: "90" }, "90 days")
            ])
          ]),
          revenue &&
            h(GlassPanel, { key: "tot", className: "mb-4" }, [
              h("p", { className: "text-sm text-slate-500" }, "Period totals (non-cancelled orders)"),
              h("p", { className: "mt-1 text-lg font-bold text-slate-900 dark:text-white" },
                `Platform fees: ${formatGhc(revenue.totals?.platformFee || 0)} · Gross: ${formatGhc(revenue.totals?.gross || 0)} · Rate: ${revenue.totals?.commissionPercent ?? "—"}%`
              )
            ]),
          revenue &&
            h(GlassCard, { key: "series", className: "!mb-4 !overflow-x-auto !p-0" }, h("table", { className: "w-full min-w-[400px] text-sm" }, [
              h("thead", { className: "bg-white/20 text-xs uppercase" }, h("tr", null, [h("th", { className: "px-3 py-2" }, "Date"), h("th", { className: "px-3 py-2" }, "Platform fee"), h("th", { className: "px-3 py-2" }, "Gross"), h("th", { className: "px-3 py-2" }, "Orders")])),
              h(
                "tbody",
                { className: "divide-y divide-white/10" },
                (revenue.series || []).map((row) =>
                  h("tr", { key: row.date }, [
                    h("td", { className: "px-3 py-1.5" }, row.date),
                    h("td", { className: "px-3 py-1.5" }, formatGhc(row.platform)),
                    h("td", { className: "px-3 py-1.5" }, formatGhc(row.gross)),
                    h("td", { className: "px-3 py-1.5" }, String(row.count))
                  ])
                )
              )
            ])),
          h("h2", { className: "mb-2 text-lg font-semibold text-slate-900 dark:text-white" }, "Seller proceeds (from paid line items)"),
          h(GlassCard, { className: "!overflow-x-auto !p-0" }, h("table", { className: "w-full min-w-[480px] text-sm" }, [
            h("thead", { className: "bg-white/20 text-xs uppercase" }, h("tr", null, [h("th", { className: "px-3 py-2" }, "Seller"), h("th", { className: "px-3 py-2" }, "Total proceeds"), h("th", { className: "px-3 py-2" }, "Line items")])),
            h(
              "tbody",
              { className: "divide-y divide-white/10" },
              balances.map((s) =>
                h("tr", { key: s.id }, [
                  h("td", { className: "px-3 py-2" }, [h("div", { className: "font-medium" }, s.displayName), h("div", { className: "text-xs text-slate-500" }, s.email)]),
                  h("td", { className: "px-3 py-2 font-medium" }, formatGhc(s.sellerProceedsTotal)),
                  h("td", { className: "px-3 py-2" }, String(s.lineCount))
                ])
              )
            )
          ]))
        ]),

      tab === "messages" &&
        !loading &&
        h(f, { key: "msg" }, [
          h("h1", { className: "mb-4 font-display text-2xl font-bold text-slate-900 dark:text-white" }, "Message oversight"),
          h("div", { className: "grid grid-cols-1 gap-4 lg:grid-cols-2" }, [
            h(GlassCard, { key: "list", className: "max-h-[480px] overflow-y-auto !p-0" }, h("div", { className: "divide-y divide-white/10" },
              conversations.length === 0
                ? h("p", { className: "p-4 text-sm text-slate-500" }, "No chat threads yet.")
                : conversations.map((c) =>
                    h(
                      "button",
                      {
                        key: c.id,
                        type: "button",
                        onClick: () => setSelectedThreadId(c.id),
                        className: `w-full px-4 py-3 text-left text-sm hover:bg-white/10 ${selectedThreadId === c.id ? "bg-sky-500/10" : ""}`
                      },
                      [
                        h("div", { className: "font-medium text-slate-900 dark:text-white" }, `${c.buyerLabel} ↔ ${c.sellerLabel}`),
                        h("div", { className: "text-xs text-slate-500" }, `${c.messageCount} messages · last ${c.lastMessage ? new Date(c.lastMessage.createdAt).toLocaleString() : "—"}`)
                      ]
                    )
                  )
            )),
            h(GlassPanel, { key: "detail" }, [
              !threadDetail && h("p", { className: "text-sm text-slate-500" }, "Select a thread to read messages."),
              threadDetail &&
                h("div", { className: "max-h-[400px] space-y-2 overflow-y-auto" },
                  (threadDetail.messages || []).map((m, i) =>
                    h("div", { key: i, className: "rounded-2xl border border-white/10 bg-white/5 p-2 text-sm" }, [
                      h("div", { className: "text-xs text-slate-400" }, `${m.senderRole} · ${new Date(m.createdAt).toLocaleString()}`),
                      h("p", { className: "mt-1 text-slate-200" }, m.text)
                    ])
                  )
                )
            ])
          ]),
          h("div", { className: "mt-3 flex justify-between text-sm text-slate-500" }, [
            h("span", {}, `Page ${convPage} · ${convTotal} threads`),
            h("div", { className: "flex gap-2" }, [
              h(Button, { variant: "ghost", className: "!min-h-8", disabled: convPage <= 1, onClick: () => setConvPage((p) => Math.max(1, p - 1)) }, "Prev"),
              h(Button, { variant: "ghost", className: "!min-h-8", disabled: convPage * convLimit >= convTotal, onClick: () => setConvPage((p) => p + 1) }, "Next")
            ])
          ])
        ]),

      tab === "reports" &&
        !loading &&
        h(f, { key: "rep" }, [
          h("h1", { className: "mb-4 font-display text-2xl font-bold text-slate-900 dark:text-white" }, "Reports & complaints"),
          h("div", { className: "mb-4 flex items-center gap-2" }, [
            h("span", { className: "text-sm" }, "Status:"),
            h(SelectInput, { value: reportStatusFilter, onChange: (e) => { setReportStatusFilter(e.target.value); setReportPage(1); } }, 
              REPORT_STATUS_OPTS.map((o) => h("option", { key: o.v || "all", value: o.v }, o.l))
            )
          ]),
          h(GlassCard, { className: "!overflow-x-auto !p-0" }, h("table", { className: "w-full min-w-[900px] text-left text-sm" }, [
            h("thead", { className: "bg-white/20 text-xs uppercase" }, h("tr", null, [
              h("th", { className: "px-3 py-2" }, "Reporter"),
              h("th", { className: "px-3 py-2" }, "Type"),
              h("th", { className: "px-3 py-2" }, "Target"),
              h("th", { className: "px-3 py-2" }, "Status"),
              h("th", { className: "px-3 py-2" }, "Description"),
              h("th", { className: "px-3 py-2" }, "Set status")
            ])),
            h(
              "tbody",
              { className: "divide-y divide-white/10" },
              reports.map((r) =>
                h("tr", { key: r.id, className: "align-top" }, [
                  h("td", { className: "px-3 py-2" }, r.reporterLabel),
                  h("td", { className: "px-3 py-2" }, REPORT_CATS[r.category] || r.category),
                  h("td", { className: "px-3 py-2" }, [r.targetType, r.targetId ? h("div", { className: "font-mono text-xs" }, r.targetId) : null]),
                  h("td", { className: "px-3 py-2" }, h(Badge, { tone: r.status === "open" ? "warn" : "neutral" }, r.status)),
                  h("td", { className: "max-w-xs px-3 py-2 text-slate-600" }, r.description?.slice(0, 200) + (r.description?.length > 200 ? "…" : "")),
                  h("td", { className: "px-3 py-2" }, h(SelectInput, { 
                    value: r.status, 
                    onChange: (e) => patchReportStatus(r, e.target.value) 
                  }, [
                    h("option", { value: "open" }, "open"),
                    h("option", { value: "in_review" }, "in_review"),
                    h("option", { value: "resolved" }, "resolved"),
                    h("option", { value: "dismissed" }, "dismissed")
                  ]))
                ])
              )
            )
          ])),
          h("div", { className: "mt-3 flex justify-between text-sm text-slate-500" }, [
            h("span", {}, `Page ${reportPage} · ${reportTotal} reports`),
            h("div", { className: "flex gap-2" }, [
              h(Button, { variant: "ghost", className: "!min-h-8", disabled: reportPage <= 1, onClick: () => setReportPage((p) => Math.max(1, p - 1)) }, "Prev"),
              h(Button, { variant: "ghost", className: "!min-h-8", disabled: reportPage * reportLimit >= reportTotal, onClick: () => setReportPage((p) => p + 1) }, "Next")
            ])
          ])
        ]),

      tab === "settings" &&
        !loading &&
        h(f, { key: "set" }, [
          h("h1", { className: "mb-4 font-display text-2xl font-bold text-slate-900 dark:text-white" }, "Platform settings"),
          h(GlassPanel, { key: "pf" }, [
            h("p", { className: "text-sm text-slate-500" }, "Commission applies to new checkouts. Existing orders keep stored line fees."),
            h(Field, { className: "mt-3", label: "Commission % (0–100)" }, h(TextInput, { type: "number", value: String(settingsForm.commissionPercent), onChange: (e) => setSettingsForm((s) => ({ ...s, commissionPercent: Number(e.target.value) })) })),
            h("div", { className: "mt-4 space-y-2" }, [
              h("label", { className: "flex items-center gap-2 text-sm" }, [h("input", { type: "checkbox", checked: settingsForm.momoEnabled, onChange: (e) => setSettingsForm((s) => ({ ...s, momoEnabled: e.target.checked })) }), " MoMo / off-platform (buyer instructions)"]),
              h("label", { className: "flex items-center gap-2 text-sm" }, [h("input", { type: "checkbox", checked: settingsForm.stripeEnabled, onChange: (e) => setSettingsForm((s) => ({ ...s, stripeEnabled: e.target.checked })) }), " Stripe checkout (if configured)"]),
              h("label", { className: "flex items-center gap-2 text-sm" }, [h("input", { type: "checkbox", checked: settingsForm.bankEnabled, onChange: (e) => setSettingsForm((s) => ({ ...s, bankEnabled: e.target.checked })) }), " Bank / manual (buyer info)"])
            ]),
            h(Field, { className: "mt-4", label: "Listing / policy note (for your team; storefront hook optional)" }, h(TextArea, { value: settingsForm.listingPolicyNote, onChange: (e) => setSettingsForm((s) => ({ ...s, listingPolicyNote: e.target.value })), rows: 4 })),
            h(Button, { className: "mt-4", loading: savingSettings, onClick: saveSettings }, "Save settings")
          ])
        ])
    ])
  ]);
}
